head.script:
scwin.gVar = {
    "cNextTabIDTarget" : "",
    "cNextTabIDInput" : "",
    "cNextTabIDButton" : "",
    "cNextTabIDSelectBox" : "",
    "cDisabled" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > nextTabID]<br/>Tab 키로 포커스 이동 시 포커스가 이동될 다음 컴포넌트의 ID 를 설정합니다.",
    "validation" : [
        "포커스가 이동될 컴포넌트의 ID 를 설정합니다.",
        "존재하지 않는 ID 설정 시 적용되지 않으며 다른 Scope 의 컴포넌트는 설정할 수 없습니다.",
        "값을 설정하지 않으면 일반적인 tabIndex 규칙을 따릅니다.",
        "tabIndex 속성에 의한 순서는 무시되고 nextTabID 에 설정된 컴포넌트로 포커스가 이동합니다.",
        "Shift+Tab 키로 포커스를 이전으로 이동하면 현재 포커스된 컴포넌트를 nextTabID 속성에 설정한 컴포넌트로 포커스가 이동됩니다.",
        "현재 포커스된 컴포넌트가 두 개 이상의 nextTabID 에 설정된 경우 소스에서 마지막에 정의된 컴포넌트로 포커스가 이동합니다.",
        "nextTabID 에 설정한 컴포넌트가 포커스를 받을 수 없는 상태(disabled 등)이고 해당 컴포넌트에 nextTabID 가 설정되어 있으면 다음 컴포넌트로 포커스가 이동합니다.",
        "nextTabID 에 설정한 컴포넌트가 포커스를 받을 수 없는 상태(disabled 등)이고 해당 컴포넌트에 nextTabID 가 설정되어 있지 않으면 tabIndex 속성과 관계없이 포커스가 이동하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (자체 값 selectbox 는 value)
    con_nextTabID_target.setValue("button2");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof startcomp !== 'undefined') {
        startcomp.remove();
    }

    if (typeof input2 !== 'undefined') {
        input2.remove();
    }

    if (typeof button2 !== 'undefined') {
        button2.remove();
    }

    if (typeof selectbox2 !== 'undefined') {
        selectbox2.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] tabIndex 는 startcomp 1, target1 2, input2 3, button2 4, selectbox2 5 로 고정하며 생성(소스 정의) 순서는 startcomp, input2, button2, selectbox2, target1 입니다\n[절차] 조건 선택 -> Target 재생성 -> 정방향은 startcomp 를 클릭한 뒤 Tab 키를 반복해서 누르고, 역방향은 button2 를 클릭한 뒤 Shift+Tab 키를 반복해서 누릅니다 (selectbox2 는 클릭 시 내부 요소에 포커스가 머물러 Shift+Tab 시작점으로 부적합)\n[확인] 결과창에 누적되는 포커스 이동 경로 (한 줄이 Tab 한 번의 도착지)\n[참고] 현행 엔진에서는 Secret 의 nextTabID 속성이 동작하지 않아 모든 조건에서 tabIndex 순서로만 이동합니다 (WAEA-1233 미해결)"', '', 'label1');

    // 조건 설정
    scwin.gVar["cNextTabIDTarget"] = con_nextTabID_target.getValue();
    scwin.gVar["cNextTabIDInput"] = con_nextTabID_input.getValue();
    scwin.gVar["cNextTabIDButton"] = con_nextTabID_button.getValue();
    scwin.gVar["cNextTabIDSelectBox"] = con_nextTabID_selectbox.getValue();
    scwin.gVar["cDisabled"] = con_disabled.getValue();

    // nextTabID 대상 컴포넌트는 target1 보다 먼저 생성되어야 매칭된다
    await $c.gcm.createBasicInput($c.gcm.createCList({ tabIndex : "1" }), 'ev:onfocus="scwin.startcomp_onfocus"', "startcomp");

    let properties_input = {
        tabIndex : "3",
        nextTabID : scwin.gVar["cNextTabIDInput"],
        disabled : (scwin.gVar["cDisabled"] === "input2") ? "true" : "",
    }

    await $c.gcm.createBasicInput($c.gcm.createCList(properties_input), 'ev:onfocus="scwin.input2_onfocus"', "input2");

    let properties_button = {
        tabIndex : "4",
        nextTabID : scwin.gVar["cNextTabIDButton"],
        disabled : (scwin.gVar["cDisabled"] === "button2") ? "true" : "",
    }

    await $c.gcm.createBasicButton($c.gcm.createCList(properties_button), 'ev:onfocus="scwin.button2_onfocus"', "button2");

    let properties_selectbox = {
        tabIndex : "5",
        nextTabID : scwin.gVar["cNextTabIDSelectBox"],
        disabled : (scwin.gVar["cDisabled"] === "selectbox2") ? "true" : "",
    }

    await $c.gcm.createBasicSelectBox($c.gcm.createCList(properties_selectbox), 'ev:onfocus="scwin.selectbox2_onfocus"', "selectbox2");

    let properties = {
        tabIndex : "2",
        nextTabID : scwin.gVar["cNextTabIDTarget"],
    }

    let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출
    await $c.gcm.createBasicSecret(cList, 'ev:onfocus="scwin.target1_onfocus"');

    startcomp.setValue("startcomp");
}



// 포커스가 도착한 컴포넌트를 순서대로 출력 (누적된 줄이 이동 경로) - validation 1 ~ 8 판정 출력
scwin.printFocus = function (strID) {
    let strTarget = (scwin.gVar["cNextTabIDTarget"] === "") ? "미설정" : scwin.gVar["cNextTabIDTarget"];
    let strInput = (scwin.gVar["cNextTabIDInput"] === "") ? "미설정" : scwin.gVar["cNextTabIDInput"];
    let strButton = (scwin.gVar["cNextTabIDButton"] === "") ? "미설정" : scwin.gVar["cNextTabIDButton"];
    let strSelectBox = (scwin.gVar["cNextTabIDSelectBox"] === "") ? "미설정" : scwin.gVar["cNextTabIDSelectBox"];
    let strDisabled = (scwin.gVar["cDisabled"] === "") ? "미설정" : scwin.gVar["cDisabled"];

    wf_body_bottom.getObj("scwin").setReturnValue("nextTabID target1 " + strTarget + " / input2 " + strInput + " / button2 " + strButton + " / selectbox2 " + strSelectBox + " / disabled " + strDisabled + " -> 포커스 : " + strID);
}



// 테스트 샘플의 이벤트 처리 (포커스 획득)
scwin.startcomp_onfocus = function (e) {
    scwin.printFocus("startcomp");
}



scwin.target1_onfocus = function (e) {
    scwin.printFocus("target1");
}



scwin.input2_onfocus = function (e) {
    scwin.printFocus("input2");
}



scwin.button2_onfocus = function (e) {
    scwin.printFocus("button2");
}



scwin.selectbox2_onfocus = function (e) {
    scwin.printFocus("selectbox2");
}
